    { href: '/offers', label: t.navigation?.myOffers || 'Moje Oferty', icon: '📋' },
    // Panel admina tylko dla roli 'admin'.
    ...(role === 'admin'
      ? [{ href: '/admin', label: t.navigation?.panelAdmin || 'Panel Admina', icon: '⚙️' }]
      : []),
  ];

