218	    if (!items || !Array.isArray(items) || items.length === 0) {
219	      return NextResponse.json({ error: 'No items provided' }, { status: 400 });
220	    }
221	
222	    const client: ClientInfo = clientInfo || { firstName: '', lastName: '', company: '', address: '', nip: '', phone: '', email: '' };
223	    const userName = session.email || '';
224	    const date = offerDate || new Date().toLocaleDateString('pl-PL');
225	
226	    const html_content = buildHtml(items, client, offerName || '', date, userName);
227	
228	    // Step 1: Create PDF request
229	    const createResponse = await fetch('https://apps.abacus.ai/api/createConvertHtmlToPdfRequest', {
230	      method: 'POST',
231	      headers: { 'Content-Type': 'application/json' },
232	      body: JSON.stringify({
233	        deployment_token: process.env.ABACUSAI_API_KEY,
234	        html_content,
235	        pdf_options: { format: 'A4', landscape: true, print_background: true, margin: { top: '10mm', right: '10mm', bottom: '15mm', left: '10mm' } },
236	        base_url: process.env.NEXTAUTH_URL || '',
237	      }),
238	    });
239	
240	    if (!createResponse.ok) {
241	      const err = await createResponse.json().catch(() => ({ error: 'PDF request failed' }));
242	      console.error('PDF create error:', err);
243	      return NextResponse.json({ success: false, error: err.error || 'PDF request failed' }, { status: 500 });
244	    }
245	
246	    const { request_id } = await createResponse.json();
247	    if (!request_id) {
248	      return NextResponse.json({ success: false, error: 'No request ID' }, { status: 500 });
249	    }
250	
251	    // Step 2: Poll for completion
252	    const maxAttempts = 120;
253	    let attempts = 0;
254	    while (attempts < maxAttempts) {
255	      await new Promise(resolve => setTimeout(resolve, 1500));
256	      const statusResponse = await fetch('https://apps.abacus.ai/api/getConvertHtmlToPdfStatus', {
257	        method: 'POST',
258	        headers: { 'Content-Type': 'application/json' },
259	        body: JSON.stringify({ request_id, deployment_token: process.env.ABACUSAI_API_KEY }),
